Ext.define('BNK.view.HumanResource.hwm.HwmOvtAply51MViewController', {
    extend: 'Ext.app.ViewController',
    alias: 'controller.HwmOvtAply51MVIewController',

    config: {
        viewId: 'HwmOvtAply51M'
    },

    onChangeChkBox: function() {
        var me = this;
        var refs = me.getReferences();

        if(!refs.infoArea.getHidden()){
            refs.infoArea.setHidden(true);
        }
    },

    onTapAgree: function(button, e, eOpts) {
        var me = this;
        var refs = me.getReferences();

        var checkBoxes = refs.contentArea.query('checkbox');
        for(var i in checkBoxes){
            if(checkBoxes[i].getChecked() === false){
                Ext.Msg.show({
                    buttons :  {
                        yes : {itemId : Ext.MessageBox.YES, text : '확인'}
                    },
                    title : '안내',
                    message : '동의하지 않을 경우 시간외 근무 신청이 불가합니다.',
                    alwaysOnTop : true,
                    fn : function(btn) {
                        return;
                    }
                });
                return;
            }
        }

        me.getView().fireEvent('agree'); //fireEvent 전달
        me.getView().close();
    },

    onTapCancle: function(button, e, eOpts) {
        var me = this;
        me.getView().close();
    },

    init: function(component, eOpts) {
        var me = this;
        var refs = me.getReferences();

        var msgList = Ext.StoreMgr.get('MessageStore').data.filterBy('code','M_HwmOvtAply51').items;
        msgList.sort(function(data1, data2) {
            data1.data.code = data1.data.code.toLowerCase();
            data2.data.code = data2.data.code.toLowerCase();
            if (data1.data.code < data2.data.code) return -1;
            if (data1.data.code > data2.data.code) return 1;
            return 0;
        });

        refs.contentArea.removeAll();
        for( var i in msgList){
            refs.contentArea.add({
                xtype : 'container',
                layout : 'hbox',
                flex : 1,
                items : [
                {
                    xtype : 'checkbox',
                    //                 checked : true,
                    listeners : {
                        change : 'onChangeChkBox'
                    }
                },
                {
                    xtype : 'container',
                    width : 10,
                },
                {
                    xtype : 'label',
                    flex : 1,
                    margin : '8 0 0 0',
                    html : msgList[i].get('text')
                }
                ]
            });
        }

    }

});